        $result = 2;
        if ($f[0] === 0 && $f[1] === 0 && $s[0] === 0 && $s[1] === 0) {
            $result = 0;
        } else if ($f[0] + $f[1] + $s[0] + $s[1] === 4) {
            $result = 2;
        } else {
            $result = 1;
        }

        output($result);
    }
}

